import{_ as t,o as e,c as o,S as r}from"./chunks/framework.y0rMCQaU.js";const p="/assets/qrcode-official-account.DOWeqZNI.jpg",u=JSON.parse('{"title":"关于","description":"","frontmatter":{},"headers":[],"relativePath":"docs/about.md","filePath":"docs/about.md"}'),s={name:"docs/about.md"};function n(i,a,c,d,l,h){return e(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="关于" tabindex="-1">关于 <a class="header-anchor" href="#关于" aria-label="Permalink to &quot;关于&quot;">​</a></h1><p>这里是<strong>季小小的碎碎念</strong></p><p>在这里，会记录一些我探索副业的想法、一些小项目，等等</p><p>希望这些内容能让你有所收获（没有的话，关闭页面就好）</p><h2 id="关于我" tabindex="-1">关于我 <a class="header-anchor" href="#关于我" aria-label="Permalink to &quot;关于我&quot;">​</a></h2><p>曾经做了四年半的前端</p><p>因为口罩，发生了一些变故，（可以看看这个 👉 <a href="https://mp.weixin.qq.com/s/aXFYUxS9galznk_jWmYJUw" target="_blank" rel="noreferrer">我的 2023</a>）</p><p>再加上环境不好，自身实力不够硬，最终选择转行，跟着家里人经营一家超市</p><p>呆店里很无聊，不是我喜欢的工作，况且以我个人拙见，超市是走下坡路的</p><p>同时，开店和做前端一样，有一个致命的问题：<strong>我没有构建出自己的核心赚钱能力</strong></p><p>做前端时，公司不好，环境不景气（或者说互联网溢价逐渐消失，回归到正常值），那么收入会受到影响</p><p>做一天才有一天工资，不敢随便请假，不敢轻易辞职，手停口停</p><p>开店时，我所依赖的是爸妈铺好的路，开一天有一天流水，后续生意也没那么好做，而且整个人会被捆绑在店里</p><p>说到底，还是过分依赖平台、环境，缺少对赚钱底层逻辑的理解</p><p>始终处于「<strong>不知道如果不做这个，还能做什么</strong>」的状态</p><p>所以，我想要折腾一些其他的，去避免<strong>一眼看到头的慢性死亡</strong></p><p>于是就有了很多副业的探索</p><p>目前来看没有什么大的成功，不过可能会对你会有一些启发</p><p>毕竟每个人情况不一样，我做不成的也许你就做成了</p><h2 id="公众号" tabindex="-1">公众号 <a class="header-anchor" href="#公众号" aria-label="Permalink to &quot;公众号&quot;">​</a></h2><p>欢迎关注公众号，虽然写的少</p><img src="'+p+'" width="200" height="200">',22)])])}const f=t(s,[["render",n]]);export{u as __pageData,f as default};
